import json
with open('baseline-packages.json') as f: b=json.load(f)
with open('after-cpm-packages.json') as f: a=json.load(f)

def extract(data):
    result={}
    for proj in data.get('projects',[]):
        name=proj['path'].split('/')[-1]
        for fw in proj.get('frameworks',[]):
            key=f\"{name}|{fw['framework']}\"
            for pkg in fw.get('topLevelPackages',[]):
                result.setdefault(key,{})[pkg['id']]=pkg.get('resolvedVersion','?')
    return result

bp=extract(b)
ap=extract(a)
changes=[]
unchanged=[]
for k in sorted(set(list(bp.keys())+list(ap.keys()))):
    bpkgs=bp.get(k,{})
    apkgs=ap.get(k,{})
    for pkg in sorted(set(list(bpkgs.keys())+list(apkgs.keys()))):
        bv=bpkgs.get(pkg,'(none)')
        av=apkgs.get(pkg,'(none)')
        if bv!=av:
            changes.append((k,pkg,bv,av))
        else:
            unchanged.append((k,pkg,bv))

print('=== CHANGES ===')
for c in changes:
    print(f'{c[0]}: {c[1]} {c[2]} -> {c[3]}')
print(f'\\n=== UNCHANGED: {len(unchanged)} packages ===' )
" 2>&1

